import{at as e,it as t,n,vt as r}from"./chunks/framework.B0lbOe_c.js";var i=JSON.parse(`{"title":"Portal","description":"","frontmatter":{"title":"Portal","covers":{"screens":["SCR-050","SCR-053"],"stories":["US-060","US-061","US-127","US-128"]}},"headers":[],"relativePath":"usage/portal.md","filePath":"usage/portal.md"}`),a={name:`usage/portal.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="portal" tabindex="-1">Portal <a class="header-anchor" href="#portal" aria-label="Permalink to “Portal”">​</a></h1><p>The portal shows the shared catalogs and the dashboards of the repository read-only. It is meant for people who read the architecture but do not work on it, for example with the role <code>portal-reader</code>. Everybody with the permission <code>portal:read</code> can open it; the roles <code>viewer</code>, <code>analyst</code> and <code>enterprise-architect</code> have it too.</p><h2 id="open-the-portal" tabindex="-1">Open the portal <a class="header-anchor" href="#open-the-portal" aria-label="Permalink to “Open the portal”">​</a></h2><ul><li>With only <code>portal:read</code> (for example the role <code>portal-reader</code>), you land on the portal after login. The header shows <em>Portal</em> as its only entry; the start page and the catalogs lead to the portal as well.</li><li>With <code>entity:read</code>, the header shows <em>Portal</em> next to <em>Catalogs</em>.</li></ul><p>The page <em>Portal</em> has two sections. <em>Shared catalogs</em> lists the <strong>shared catalogs</strong> by name, each with its entity type; personal catalogs never appear in the portal, not even your own. <em>Dashboards</em> lists the <strong>dashboards</strong> (see <a href="#dashboards">Dashboards in the portal</a>). If one list cannot be loaded, the page shows the error in its section and the other section stays usable.</p><h2 id="read-a-catalog" tabindex="-1">Read a catalog <a class="header-anchor" href="#read-a-catalog" aria-label="Permalink to “Read a catalog”">​</a></h2><p>Choose a catalog in the list. It opens with the columns, the default sort and the default join mode its owner configured.</p><ul><li><strong>Sort:</strong> choose a column header. The first click sorts ascending, the second descending, the third returns to the default order.</li><li><strong>Page:</strong> the table shows 50 rows per page; the page numbers below the table move between pages.</li><li><strong>Back:</strong> <em>Back to the portal</em> returns to the list.</li></ul><p>Sort and page are part of the address, so you can bookmark a sorted page or send it to someone. The portal offers no action that changes the catalog: no columns, joins, filters, views or navigation tree. If a catalog is no longer shared or does not exist, the page says <em>Catalog not found</em>.</p><p>The portal applies the <a href="./../administration/property-visibility">property visibility</a> like every catalog: a column on a property you may not see stays empty, and a column on a connection-based property shows the value only in the rows of entities connected to your element. With an <a href="./../administration/property-visibility#override-roles">override role</a> you see all values, and the query is recorded in the audit log.</p><h2 id="dashboards" tabindex="-1">Dashboards <a class="header-anchor" href="#dashboards" aria-label="Permalink to “Dashboards”">​</a></h2><p>The section <em>Dashboards</em> lists, ordered by name, the <strong>shared dashboards</strong> and your <strong>own personal dashboards</strong>, each with its number of widgets; personal ones carry the badge <em>Personal</em>. A personal dashboard of another person never appears, not even for administrators; they read it in the work area (see <a href="./dashboards">Dashboards</a>). Without any dashboard the section says <em>No dashboards yet.</em></p><p>Choose a dashboard to open its read-only view:</p><ul><li>The widgets sit where their owner placed them in the 12-column grid. There is no <em>Edit</em>, <em>Add widget</em> or <em>Delete</em>, and no drag handle or resize handle; the portal changes nothing.</li><li>The widgets show the same data as in the work area, computed with your permissions and the <a href="./../administration/property-visibility">property visibility</a>: a KPI over a property you may not read for every entity says so instead of showing a value, and a widget that cannot be computed (for example because its catalog is gone) shows its message while the others render normally.</li><li>A table widget pages through <em>Page x of y</em>. Its rows do not link to an entity; the portal has no entity detail yet.</li><li>The page shows the time of the data (<em>Data as of …</em>). <strong>Refresh</strong> reads the data again; the page does not update on its own.</li><li><em>Back to the portal</em> returns to the list. If the dashboard does not exist or is not visible to you, the page says <em>Dashboard not found</em>.</li></ul><p>If you hold only <code>portal:read</code> and open the address of a dashboard of the work area (<code>/dashboards</code> or <code>/dashboards/{id}</code>), you are taken to the portal, or to the same dashboard in the portal.</p><h2 id="through-the-api" tabindex="-1">Through the API <a class="header-anchor" href="#through-the-api" aria-label="Permalink to “Through the API”">​</a></h2><ul><li><code>GET /portal/catalogs</code> lists the shared catalogs, ordered by name.</li><li><code>GET /portal/catalogs/{id}/query</code> returns one page of a shared catalog with <code>page</code>, <code>pageSize</code> (at most 200) and <code>sort</code> (<code>{column}:{asc|desc}</code>), the same result as <code>GET /catalogs/{id}/query</code> without filters, join mode overrides or views.</li><li>The next page can be read with <code>cursor</code> (the <code>nextCursor</code> of the previous page) and <code>page</code> + 1, and a query above the time limit answers 503 <code>query-timeout</code>, as in the catalog query (see <a href="./catalogs#browse">Catalogs</a>). A cursor of the catalog query is not valid in the portal. Columns on properties you may not see are empty, as in the catalog query.</li></ul><p>Both need <code>portal:read</code>. A personal catalog answers 404, an invalid parameter 400 with the parameter in <code>invalidFields</code>.</p><p>The dashboards of the portal need <code>portal:read</code> only:</p><ul><li><code>GET /portal/dashboards</code> lists the shared dashboards and your own personal ones, ordered by name, each with <code>canEdit: false</code>.</li><li><code>GET /portal/dashboards/{id}</code> returns the configuration (widgets, titles, settings and grid positions), <code>GET /portal/dashboards/{id}/data</code> the data of all widgets, and <code>GET /portal/dashboards/{id}/widgets/{widgetId}/data?page=</code> another page of a table widget (from 0; a negative page answers 400). The answers have the shape of the work-area reads (see <a href="./dashboards#api">Dashboards</a>), the configuration always with <code>canEdit: false</code> and without an <code>ETag</code>. A table widget that exceeds the time limit of its catalog query answers 503 <code>query-timeout</code>.</li><li>Another person&#39;s personal dashboard and an unknown dashboard or widget answer 404, also for administrators. Service accounts answer 403.</li></ul>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};